    dst.parent.mkdir(parents=True, exist_ok=True)
    dst.write_text("\n".join(out), encoding="utf-8")
    print(f"{dst}  ({dst.stat().st_size / 1024:.0f} KB, {turn} user turns)")


if __name__ == "__main__":
